create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, phone text, cpf text, course text, data jsonb not null default '{}'::jsonb, created_date timestamptz not null default now(), updated_date timestamptz not null default now());
grant select, insert, update on public.profiles to authenticated; grant all on public.profiles to service_role;
alter table public.profiles enable row level security;
create policy "own profile read" on public.profiles for select to authenticated using (id = auth.uid());
create policy "own profile insert" on public.profiles for insert to authenticated with check (id = auth.uid());
create policy "own profile update" on public.profiles for update to authenticated using (id = auth.uid());
create type public.app_role as enum ('admin','user');
create table public.user_roles(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, unique(user_id, role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy "own roles" on public.user_roles for select to authenticated using (user_id = auth.uid());
create table public.legacy_user_map(base44_user_id text primary key, email text not null, auth_user_id uuid, role text, full_name text, data jsonb default '{}'::jsonb, linked_at timestamptz);
grant all on public.legacy_user_map to service_role;
alter table public.legacy_user_map enable row level security;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin
  insert into public.profiles(id,email,full_name) values (new.id, lower(new.email), coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name')) on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.set_updated_date() returns trigger language plpgsql set search_path=public as $$ begin new.updated_date = now(); return new; end $$;
create or replace function public._std(t text) returns void language plpgsql as $f$
begin
  execute format('alter table public.%I add column id text primary key default replace(gen_random_uuid()::text,''-'',''''), add column created_date timestamptz not null default now(), add column updated_date timestamptz not null default now(), add column created_by text', t);
  execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_date()', t||'_upd', t);
  execute format('grant all on public.%I to service_role', t);
  execute format('alter table public.%I enable row level security', t);
end $f$;
create or replace function public._admin_all(t text) returns void language plpgsql as $f$
begin
  execute format('grant select, insert, update, delete on public.%I to authenticated', t);
  execute format('create policy "admin all" on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())', t);
end $f$;
create or replace function public.is_admin() returns boolean language plpgsql stable security definer set search_path=public as $$
begin
  return exists(select 1 from public.user_roles where user_id = auth.uid() and role = 'admin')
    or exists(select 1 from public.staff_profile s where s.active is not false and (s.user_id = auth.uid()::text or lower(s.user_email) = lower(auth.jwt()->>'email')) and (jsonb_array_length(coalesce(s.roles,'[]'::jsonb))>0 or jsonb_array_length(coalesce(s.permissions,'[]'::jsonb))>0));
end $$;
grant execute on function public.is_admin() to anon, authenticated;
